const state = items[0]?.json?.state || items[0]?.json || {};
const now = new Date().toISOString();
const facts = state.research?.financials?.raw_us_gaap_facts || {};
const metrics = state.normalized?.metrics || {};
function tagRows(tags) {
  for (const tag of tags) {
    const fact = facts[tag];
    if (!fact?.units) continue;
    const rows = Object.values(fact.units).flat().filter((row) => row && row.val !== undefined);
    if (rows.length) return { tag, rows };
  }
  return { tag: tags[0], rows: [] };
}
const tagMap = {
  revenue: ['RevenueFromContractWithCustomerExcludingAssessedTax','Revenues','SalesRevenueNet'],
  gross_profit: ['GrossProfit'],
  operating_income: ['OperatingIncomeLoss'],
  net_income: ['NetIncomeLoss','ProfitLoss'],
  depreciation_amortization: ['DepreciationDepletionAndAmortization','DepreciationDepletionAndAmortizationExpense','DepreciationAndAmortization'],
  diluted_eps: ['EarningsPerShareDiluted'],
  long_term_debt: ['LongTermDebtAndFinanceLeaseObligationsNoncurrent','LongTermDebtNoncurrent','LongTermDebtAndFinanceLeaseObligationsCurrent'],
  operating_cash_flow: ['NetCashProvidedByUsedInOperatingActivities','NetCashProvidedByUsedInOperatingActivitiesContinuingOperations'],
  capex: ['PaymentsToAcquirePropertyPlantAndEquipment','PaymentsToAcquireProductiveAssets']
};
function source(row, tag, formula) {
  return { source_name: `SEC EDGAR Company Facts:${tag}`, source_url: state.research?.financials?.source_url || '', source_date: row?.filed || now, source_section: row?.form || 'companyfacts', formula: formula || null, confidence: row ? 'HIGH' : 'N/A' };
}
function latestBy(rows, predicate) {
  return rows.filter(predicate).sort((a,b) => String(a.end || '').localeCompare(String(b.end || '')) || String(a.filed || '').localeCompare(String(b.filed || ''))).at(-1) || null;
}
function annual(tagKey, fy) {
  const found = tagRows(tagMap[tagKey] || [tagKey]);
  const row = latestBy(found.rows, (r) => r.form === '10-K' && Number(r.fy) === Number(fy));
  return row ? { value: row.val, unit: inferUnit(tagKey), period: `FY${fy}`, fiscal_label: `FY${fy}`, ...source(row, found.tag) } : null;
}
function quarterly(tagKey, q) {
  if (!q) return null;
  const found = tagRows(tagMap[tagKey] || [tagKey]);
  const row = latestBy(found.rows, (r) => r.form === '10-Q' && Number(r.fy) === Number(q.fy) && String(r.fp) === String(q.fp));
  return row ? { value: row.val, unit: inferUnit(tagKey), period: `${q.fp} FY${q.fy}`, fiscal_label: `${q.fp} FY${q.fy}`, ...source(row, found.tag) } : null;
}
function inferUnit(key) { return key === 'diluted_eps' ? 'USD/share' : 'USD'; }
function qPeriods() {
  const found = tagRows(tagMap.revenue);
  const rows = found.rows.filter((r) => r.form === '10-Q' && r.fy && r.fp).sort((a,b) => String(a.end || '').localeCompare(String(b.end || '')) || String(a.filed || '').localeCompare(String(b.filed || '')));
  const unique = [];
  for (const row of rows) {
    const key = `${row.fy}-${row.fp}`;
    if (!unique.some((p) => p.key === key)) unique.push({ key, fy: row.fy, fp: row.fp, end: row.end });
  }
  const latest = unique.at(-1) || null;
  const previous = unique.at(-2) || null;
  const sameLastYear = latest ? unique.find((p) => Number(p.fy) === Number(latest.fy) - 1 && p.fp === latest.fp) || null : null;
  return { latest, previous, sameLastYear };
}
function computed(name, inputs, fn, unit, formula) {
  if (inputs.some((x) => !x || x.value === undefined || x.value === null) || (inputs[1] && Number(inputs[1].value) === 0)) return null;
  return { value: fn(...inputs.map((x) => Number(x.value))), unit, period: inputs[0].period, fiscal_label: inputs[0].fiscal_label, source_name: inputs.map((x) => x.source_name).join(' + '), source_url: inputs.map((x) => x.source_url).filter(Boolean).join(' | '), source_date: inputs.map((x) => x.source_date).filter(Boolean).sort().at(-1) || now, source_section: 'computed', formula, confidence: inputs.every((x) => x.confidence === 'HIGH') ? 'HIGH' : 'MEDIUM' };
}
function formatCell(cell) {
  if (!cell) return { display: 'N/A', value: null, reason: 'Required source line item was not available.', confidence: 'N/A' };
  return { display: `${cell.value} ${cell.unit || ''}`.trim(), ...cell };
}
const qp = qPeriods();
const periodDefs = [
  { key: 'latest_quarter', label: 'Latest Reported Quarter', type: 'quarter', q: qp.latest },
  { key: 'previous_quarter', label: 'Previous Quarter', type: 'quarter', q: qp.previous },
  { key: 'same_quarter_last_year', label: 'Same Quarter Last Year', type: 'quarter', q: qp.sameLastYear },
  ...[2025,2024,2023,2022,2021].map((fy) => ({ key: String(fy), label: String(fy), type: 'annual', fy }))
];
function baseMetric(metric, period) { return period.type === 'quarter' ? quarterly(metric, period.q) : annual(metric, period.fy); }
function metricFor(rowId, period) {
  const revenue = baseMetric('revenue', period);
  if (rowId === 'revenue') return revenue;
  if (rowId === 'operating_margin') return computed(rowId, [baseMetric('operating_income', period), revenue], (op, rev) => op / rev, 'ratio', 'Operating income / revenue');
  if (rowId === 'net_margin') return computed(rowId, [baseMetric('net_income', period), revenue], (ni, rev) => ni / rev, 'ratio', 'Net income / revenue');
  if (rowId === 'ebitda') {
    const op = baseMetric('operating_income', period); const da = baseMetric('depreciation_amortization', period);
    return computed(rowId, [op, da], (a,b) => a + b, 'USD', 'Approximate EBITDA = operating income + depreciation and amortization');
  }
  if (rowId === 'eps') return baseMetric('diluted_eps', period);
  if (rowId === 'long_term_debt') return baseMetric('long_term_debt', period);
  if (rowId === 'free_cash_flow') return computed(rowId, [baseMetric('operating_cash_flow', period), baseMetric('capex', period)], (ocf, capex) => ocf - capex, 'USD', 'Operating cash flow - capital expenditures');
  if (rowId === 'market_cap') {
    const mc = state.research?.market_data?.market_cap_usd;
    if (mc === null || mc === undefined) return null;
    return { value: mc, unit: 'USD', period: state.research?.market_data?.source_date || 'latest', fiscal_label: 'Market cap', source_name: state.research?.market_data?.source_name || 'Market data', source_url: state.research?.market_data?.source_url || '', source_date: state.research?.market_data?.source_date || now, source_section: 'market_data', formula: 'Share price x diluted shares outstanding (SEC)', confidence: state.research?.market_data?.confidence || 'MEDIUM' };
  }
  return null;
}
const rowDefs = [
  ['revenue','Revenue'], ['operating_margin','Operating Margin'], ['net_margin','Net Margin'], ['ebitda','EBITDA'], ['eps','EPS (diluted if available)'], ['long_term_debt','Long-term Debt'], ['free_cash_flow','Free Cash Flow (FCF)'], ['market_cap','Market Cap']
];
const rows = rowDefs.map(([id,label]) => ({ metric: id, label, cells: Object.fromEntries(periodDefs.map((p) => [p.label, formatCell(metricFor(id, p))])) }));
const markdown = ['## Section 2: Financial Snapshot Table (USD)', '', '| Metric | ' + periodDefs.map((p) => p.label).join(' | ') + ' |', '|---|' + periodDefs.map(() => '---').join('|') + '|', ...rows.map((row) => `| ${row.label} | ${periodDefs.map((p) => row.cells[p.label].display).join(' | ')} |`), '', 'Notes: Monetary figures are in USD when available. N/A means the required source line item was not found or could not be defensibly computed. EBITDA is approximated only when operating income and depreciation/amortization are available. Market cap remains N/A unless a free public price source and share count are available.'].join('\n');
state.financial_snapshot = { generated_at: now, currency: 'USD', periods: periodDefs, rows, markdown };
state.sections = state.sections || {};
state.sections.s2_snapshot = markdown;
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: now, workflow_name: 'WF_FINANCIAL_SNAPSHOT', status: 'OK', message: 'Exact founder financial snapshot table prepared with N/A gaps where data is unavailable.' });
return [{ json: state }];

